-- GENERATED by `wfj generate` from data/gossip/gossip-a0.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a0073f439388f3a2"] = { "Belgrom ci ha mandati qui da Orgrimmar per aiutarlo in un'⟦Alliance=Alleanza⟧ poco saggia, ma se la sua scommessa riuscirà, ne trarrà grande beneficio tutta l'⟦Horde=Orda⟧.\n\nTroppi orchi sono già morti per il suo desiderio di compiacere le donne, ma lui ci comanda ancora, e il nostro onore ci impone di trarre il meglio da questa situazione.", "." },
  ["a00ca7c518d34d37"] = { "Hai ucciso ⟦Ghost Howl=Lupo Fantasma⟧. Sei un mito!", "." },
  ["a013a43334a6ae8f"] = { "Aiutateci, vi prego! Il principe è impazzito!", "." },
  ["a013eaf26c2d83f6"] = { "Dai solo un'occhiata alla mia merce, o c'è qualcosa di specifico che posso aiutarti a trovare oggi?", "." },
  ["a019d99d39b1be0d"] = { "Sono <pronto/pronta> a scoprire dove si cela il mio destino!", "." },
  ["a01bdc72ef129207"] = { "Raccontami ancora delle torri...", "." },
  ["a023463f4c646c06"] = { "A me personalmente non dava fastidio. Era il principe a non tollerare un elfo alto nel suo dominio. Ahimè, non sono il tipo da mettere in discussione il principe. A sua discolpa, non ha incenerito mastro Winthalus all'istante.", "." },
  ["a025530b1e2b79fa"] = { "Lunga vita alle Fauci di Drago! Muori, {race} buono a nulla!", "." },
  ["a0290de58e8177dd"] = { "Carneficina! Che io possa versare sangue nel Suo nome!", "." },
  ["a02d7676c1bb4550"] = { "Venite, eroi... Per volere del Re dei Lich, sarete distrutti.", "." },
  ["a038b4254dc16ee2"] = { "Finitelo...", "." },
  ["a038e3d4f6f79f4e"] = { "%s si gratta la gola.", "." },
  ["a03b334a3a149b46"] = { "Ce l'hai fatta! Urrà!\n\nMetzen è tornato in volo nelle stalle di Babbo Inverno (sì, Metzen sa volare davvero) poco fa! La polvere ha funzionato a meraviglia; lo sapevo. Hai salvato dal disastro la Festa del Grande Inverno e la Masseria Buongusto. Grazie, {name}.\n\nSenti... per quello che hai fatto, voglio che tu abbia questo. È una cosa MOLTO speciale; se hai una cavalcatura, credo che ti divertirà un sacco. Buon Grande Inverno!", "." },
  ["a04184dd5d7b3ebb"] = { "Mmh... be', sembri abbastanza capace. Se desideri davvero imparare, niente ti sbarrerà la strada! Ti guiderò nei primi passi di quello che spero sarà un cammino lungo e appagante.", "." },
  ["a044fb85be44cb8e"] = { "Ecco la mia lista, Keldric. La solita roba.", "." },
  ["a04ece07b5a68841"] = { "Dove vagano trogg e Leper Gnome sorge la nostra casa: Gnomeregan.\n\nLe nostre famiglie perdute, le nostre case perdute. Dispersi.\n\nOh, quanto rimpiango i giorni della vita spensierata a Gnomeregan, ma quei giorni non ci sono più. Dobbiamo resistere! Dobbiamo salvare Gnomeregan!", "." },
  ["a0528f04af1f8a18"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ si trova lungo il ciglio della strada, poco a nord del ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧.\n\nAl momento è sotto il controllo dell'⟦Horde=Orda⟧.", "." },
  ["a056da986371dfb0"] = { "Le mie forze non riescono a superare le difese dei Qiraji. Non potremo avvicinarci abbastanza da piazzare la tua preziosa barriera, drago.", "." },
  ["a063d5e0e8185b67"] = { "Devi imparare da qualcuno che ne sa più di me. Va' a parlare con Josef Gregorian a ⟦Undercity=Sepulcra⟧. Allora, che ci fai ancora qui?", "." },
  ["a063d6d8e3447ed3"] = { "Un alchimista? Nessun problema, {class}. Ainethil, con tutta la sua fatica e il suo impegno, è diventata l'alchimista più esperta della ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧. Se fossi in te ci andrei di corsa. Di corsa! Ora sparisci!", "." },
  ["a06536e182a08c3c"] = { "Come previsto, l'⟦Horde=Orda⟧ ha completato tutti i suoi preparativi con largo anticipo su di te e sulla tua cosiddetta ⟦Alliance=Alleanza⟧. Ci state trattenendo tutti, perché non possiamo prendere le misure finali per dare inizio alla guerra finché non avrete adempiuto ai compiti promessi.\n\nOra va' e fa' la tua parte, {race}.", "." },
  ["a06a32393ec01f52"] = { "... ops.", "." },
  ["a06a4d951de3392c"] = { "%s si ritrae per il dolore mentre il Judgement of Justice lo investe!", "." },
  ["a06de1451a5bf140"] = { "Wushoolay, la Strega della Tempesta.\n\nIl suo potere è il potere del cielo, della pioggia e della terra frantumata. Possa ella regnare di nuovo come madre dei Gurubashi.\n\nOra Wushoolay infuria sull'orlo della follia.", "." },
  ["a0710e53880ed6d2"] = { "Se il guanto è troppo grande, ti calza ancora come un guanto?", "." },
  ["a073d1e1bc7d0198"] = { "Morganus lo stalliere si trova, guarda caso, proprio davanti alle stalle.", "." },
  ["a074b50bde8ea3b5"] = { "Salve, {class}. Ho piantato il campo qui alla Granbarricata per fare i preparativi per il mio viaggio nelle ⟦Plaguelands=Terre Infette⟧. Ho sentito dire che un grande mago umano si era stabilito a ⟦Hearthglen=Valsalda⟧ non molto tempo fa. La ⟦Scarlet Crusade=Crociata Scarlatta⟧ gli aveva commissionato nuovi archi e fucili per i suoi guerrieri e cacciatori. Si dice che avesse completato un'arma straordinaria prima che la Crociata lo uccidesse.\n\nImmagino che la loro diffidenza verso l'arcano sia cresciuta.", "." },
  ["a07cf5000af55de6"] = { "Cosa? Un essere così piccolo e fragile osa chiamarmi? Non resterà impunito!", "." },
  ["a07d00fc85466b34"] = { "Ecco Ragnaros, il Signore del Fuoco! Colui che era già antico quando questo mondo era giovane! Inchinatevi davanti a lui, mortali! Inchinatevi davanti alla vostra fine!", "." },
  ["a08339d91e3c25a4"] = { "⟦Deadmines=Miniere della Morte⟧", "." },
  ["a08522b8e20ffd9f"] = { "%s inizia a lanciare un potente incantesimo.", "." },
  ["a0888a9f9d9225b0"] = { "Falthir, ho perso il mio ⟦Zandalar Madcap's Mantle=Coprispalle degli Scriteriati degli Zandalari⟧. Ne hai uno di ricambio?", "." },
  ["a08ed463765a5d4c"] = { "Ahimè, ho chiacchierato abbastanza. Se dovessi trovarti nel porto di Valanaar, cerca Elaadrin Evengale. Elaadrin un tempo era mio allievo, ma ora serve come magistro capo dell'High Order. È testardo e capace, e ora tocca a lui e ai giovani come te, {race}, portare avanti le speranze del nostro popolo.", "." },
  ["a0913ed8dcb298bd"] = { "Sì, ti prego.", "." },
  ["a095b6a6a2e0572b"] = { "Cosa vuoi che faccia, Rabine?", "." },
  ["a097fb0ec77cf499"] = { "Conosci qualcuno... o meglio, qualcosa, che si chiama Eranikus?", "." },
  ["a09d1ca3e0710369"] = { "⟦Stockade=Segrete di Roccavento⟧", "." },
  ["a0a539f38486e87b"] = { "Lo giuro, non ti ho rubato niente! Ecco, prendi un po' delle mie provviste, ma vattene!", "." },
  ["a0a55d94c2e1d096"] = { "La temperatura è di 9280 gradi Kraklenheit! Che CALDO!", "." },
  ["a0a6f9d1ea18f9a8"] = { "Mi serve un passaggio, e in fretta! Devo consegnare un messaggio importante!", "." },
  ["a0b4c3e8aad8e51e"] = { "Subordinati?", "." },
  ["a0b524422fb2981c"] = { "Parla con me per ascoltare la mia storia.", "." },
  ["a0c13fb81d4cc6c0"] = { "Finalmente la sua presa maledetta mi ha lasciato. Padre, arrivo...", "." },
  ["a0c2aec0646ca07d"] = { "Da queste parti ci sono solo pochi posti dove pescare qualcosa. Paxton li conosce tutti, e probabilmente qualcuno che non ti dirà. Perché non vai al ⟦Iceflow Lake=Lago di Ghiacciospesso⟧ a sentire cosa ti racconta?", "." },
  ["a0cadb29f02387b0"] = { "Così vicino all'amata ⟦Lakeshire=Borgolago⟧. Per la Luce, che le mie gambe mi portino ancora un po' più in là!", "." },
  ["a0d439ef1a748c52"] = { "Quante altre provviste servono per lanciare gli attacchi via terra?", "." },
  ["a0d833380040aee9"] = { "Finalmente la maledizione è spezzata. Grazie, <eroe/eroina>.", "." },
  ["a0da62574ccf6e38"] = { "Hai accettato la mia resa.", "." },
  ["a0e2c04f6ed0ed12"] = { "La possente fortezza scavata nelle viscere infuocate del ⟦Blackrock Mountain=Massiccio Roccianera⟧ fu tenuta per secoli dai sinistri nani ⟦Dark Iron=Ferroscuro⟧, finché Nefarian, l'astuto figlio del drago Alamorte, prese il controllo della parte alta della Guglia e mosse guerra ai possedimenti dei nani nelle profondità vulcaniche della montagna. Resosi conto che i nani erano guidati dal possente elementale del fuoco Ragnaros, Nefarian giurò di schiacciare i suoi nemici e prendersi l'intero ⟦Blackrock Mountain=Massiccio Roccianera⟧.", "." },
  ["a0e315cfd9898417"] = { "Bene, ci è appena giunta voce che una carovana sta partendo da Thelsamar. È ora di muoversi! Via, via, via!", "." },
  ["a0eb60f95b96ba00"] = { "Gloria all'⟦Horde=Orda⟧ e morte ai nostri nemici, {name}!\n\nI demoni di ⟦Desolace=Desolanda⟧ sono una minaccia più grande che mai. La mia speranza di tornare dal Capoguerra si affievolisce man mano che appaiono sempre più di queste creature immonde.\n\nA volte vorrei che avessimo a che fare solo con i centauri.", "." },
  ["a0f3dbf8a8aa7c50"] = { "Forse stavolta siete riusciti a fermarci, ma torneremo... questo te lo assicuriamo!", "." },
  ["a0f4c252a192cfc5"] = { "%s tenta di lanciare ⟦Death Pact=Patto con la Morte⟧ sui suoi servitori!", "." },
  ["a0f57510b493544b"] = { "Per la Grande Madre!", "." },
  ["a0f6fbad7623b508"] = { "Devo portare questo a ⟦Ratchet=Porto Paranco⟧, e niente mi fermerà!", "." },
  ["a0fa45a87b055e5c"] = { "Ehilà, <signore/signorina>. Fai attenzione a dove metti i piedi da queste parti: ho perso una bomba travestita da topo e non riesco a trovarla.", "." },
})
